cd /scr/wurgaft/auto-psych/agent_trees/88c1bd3cf1e5f7a8/repo/_runs/cell_1/experiment2/model_loop; cat > iter_2/candidate_2/scratch/verify2.py <<'EOF'
import sys, time, numpy as np, pandas as pd, pymc as pm
sys.path.insert(0,'iter_2/candidate_2'); sys.path.insert(0,'models')
import candidate as c, digit_sum_concepts as m
d=pd.read_csv('responses.csv'); y=d.rating.values
th=[-0.6405,-0.0419,-2.2805,-4.87,20.,0.612]
vals={'lambda_0_logodds__':th[0],'gamma':th[1],'log_sum_share':th[2],'beta':th[5],'lapse_logodds__':th[3],'guess_yes_logodds__':th[4]}
for mod,b in [(c,0.0),(c,0.612),(m,None)]:
    o=mod.prepare_observed(d.to_dict('records'))
    with mod.model: pm.set_data(o)
    f=mod.model.compile_fn(mod.model['p_yes'],point_fn=True)
    pt_={k:np.array(v) for k,v in vals.items() if k in [mod.model.rvs_to_values[r].name for r in mod.model.free_RVs]}
    if b is not None: pt_['beta']=np.array(b)
    p=f(pt_); print(mod.__name__,b,-(y*np.log(p)+(1-y)*np.log(1-p)).sum())
    if mod is c and b:
        dl=mod.model.compile_dlogp(); t=time.time()
        for _ in range(20): dl(pt_)
        print('grad ms',(time.time()-t)/20*1000)
EOF
